// th16_s5_mb1: TH16 v1.00a Stage 5 midboss MBoss1.
// Source: st05mbs.ecl.txt:40-72 (entry), deps :74-206 and default.ecl.txt:202-212.
// Shell: transcribe/th16/validation.md independent-invuln wrapper.

const TIME_LIMIT: int = 1504;      // 120 opening buffer + 1380 source interrupt + 4 startup slack
const OPENING_BUFFER: int = 120;

// TH16 type 11 / type 18 appearance aliases (copied from transcribe/th16/touhou-bullets.ecl).
const TH16_TALISMAN: int = 528;
const TH16_BIG_BALL: int = 640;

// st05mbs.ecl.txt:111/163 ANGLE_ACCEL a=600 r=0.012 s=+-0.017453292 (1 deg/frame);
// :110/162 OFFSCREEN a=240 b=0.
xformdef AT_TURN_POS {
    set_ang_vel(1deg);
    set_accel(0.012fx);
    offscreen_keep(240);
}
xformdef AT_TURN_NEG {
    set_ang_vel(-1deg);
    set_accel(0.012fx);
    offscreen_keep(240);
}

// st05mbs.ecl.txt:58/67 moveRand(60, 4, 1.0f), limit from :42 moveLimit(0,128,280,64).
// Inner direction zone x+-70, y112..144; actual clamp x+-140, y96..160 (width/height/4).
sub mr_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var sp: fx = 0fx;
    if k < 60 { sp = ((60 - k) as fx) / 60fx; }
    var nx: fx = $self_x + self_fx(0) * sp;
    var ny: fx = $self_y + self_fx(1) * sp;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
sub mr_begin(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    mr_next_step();
}
sub mr_move_rand() {
    // Signed unit random * pi, kept as unwrapped BAM ints like the source.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    mr_begin(a as angle);
}
sub mr_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        mr_next_step();
    }
}

// st05mbs.ecl.txt:74-124 MBoss1_at: mode3 fixed ring, 8 volleys, base -2deg each.
// dist = etDist 20 - 4*initial speed (ANIM :109 retract displacement).
sub at_body(n: int, sp: fx, d: fx) {
    sh_reset(0);
    sh_sprite(0, TH16_TALISMAN, 10);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_speed(0, sp, 0fx);
    sh_dist(0, d);
    sh_xform(0, AT_TURN_POS);
    var a: angle = 90deg;
    for i in 0..8 {
        sh_angle(0, a, 0deg);
        sh_fire(0);
        wait(20);
        a = a - 2deg;
    }
}

// st05mbs.ecl.txt:126-176 MBoss1_at1B: same ring, base +2deg each.
sub at1b_body(n: int, sp: fx, d: fx) {
    sh_reset(2);
    sh_sprite(2, TH16_TALISMAN, 10);
    sh_ring(2, 1);
    sh_aim(2, 0);
    sh_count(2, n, 1);
    sh_speed(2, sp, 0fx);
    sh_dist(2, d);
    sh_xform(2, AT_TURN_NEG);
    var a: angle = 90deg;
    for i in 0..8 {
        sh_angle(2, a, 0deg);
        sh_fire(2);
        wait(20);
        a = a + 2deg;
    }
}

// st05mbs.ecl.txt:178-206 MBoss1_at2: mode2 aimed ring, 4 volleys, no etDist.
// The source call etDist(0,20) at :197 targets emitter 0, not the fired emitter 1,
// so only the ANIM :183 retract (-4*speed) applies here.
sub at2_body(n: int, sp: fx, d: fx) {
    sh_reset(1);
    sh_sprite(1, TH16_BIG_BALL, 2);
    sh_ring(1, 1);
    sh_aim(1, 1);
    sh_count(1, n, 1);
    sh_speed(1, sp, 0fx);
    sh_dist(1, d);
    sh_angle(1, 90deg, 0deg);
    for i in 0..4 {
        sh_fire(1);
        wait(25);
    }
}

async sub at_async(n: int, sp: fx, d: fx) {
    at_body(n, sp, d);
}
async sub at1b_async(n: int, sp: fx, d: fx) {
    at1b_body(n, sp, d);
}

// st05mbs.ecl.txt:40-72; source enemy starts at the MBoss:28-29 landing point (0,128).
async sub mboss_main() {
    set_invuln(65535);
    set_hitbox(20fx);      // MBoss:20 setHitbox(40,40) ordinary circle /2
    set_hurtbox(24fx);     // MBoss:19 setHurtbox(48,48) ordinary circle /2
    var rank: int = global(GVAR_RANK);
    var n: int = 12;
    var sp: fx = 2fx;
    var d: fx = 12fx;
    var sp2: fx = 1.5fx;
    var d2: fx = -6fx;
    if rank == RANK_NORMAL { n = 29; sp2 = 2.6fx; d2 = -10.4fx; }
    else if rank == RANK_HARD { n = 19; sp2 = 3.5fx; d2 = -14fx; }
    else if rank >= RANK_LUNATIC { n = 29; sp = 3fx; d = 8fx; sp2 = 3.5fx; d2 = -14fx; }
    loop {
        if rank >= RANK_HARD {
            spawn at1b_async(n, sp, d);
            wait(10);
        }
        at_body(n, sp, d);
        wait(20);
        at2_body(20, sp2, d2);
        mr_move_rand();
        mr_wait(70);

        if rank >= RANK_HARD {
            spawn at_async(n, sp, d);
            wait(10);
        }
        at1b_body(n, sp, d);
        wait(20);
        at2_body(20, sp2, d2);
        mr_move_rand();
        mr_wait(70);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 11000, 0, 0, 1000, mboss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
